import styled from '@emotion/styled';

export const StyledSubPillarCardsGrid = styled.div({
  display: 'grid',
  gridTemplateColumns: 'repeat(2, 1fr)',
  gap: '1rem',
  padding: '0 24px 24px 24px',

  '& [data-testid="sub-pillar-card-description"]': {
    whiteSpace: 'pre-line',
  },
});
